def rightContraction (ψ : X →L[𝕜] 𝕜) : E ⊗[𝕜] X →ₗ[𝕜] E :=
  TensorProduct.lift {
    toFun := fun e => (ψ.smulRight e).toLinearMap
    map_add' := by intro e f; ext x; exact smul_add (ψ x) e f
    map_smul' := by intro a e; ext x; exact smul_comm (ψ x) a e }

